input.sparql:
SELECT ?zone ?ts ?id WHERE {
  ?zone brick:hasPoint ?p .
  FILTER(str(?zone) LIKE "%Perimeter_%ZN_3%")
  ?p rdf:type a:AirTemperature .
  ?p ref:hasTimeseriesId ?id
}

SELECT ?zone ?p ?id WHERE {
  ?zone brick:hasPoint ?p .
  FILTER(str(?zone) LIKE "%Perimeter_%ZN_3%")
  ?p rdf:type brick:AirTemperature .
  ?p ref:hasTimeseriesId ?id
}

SELECT ?zone WHERE {
  ?zone brick:hasPoint ?p .
  ?p rdf:type brick:AirTemperature .
  ?p ref:hasTimeseriesId ?id .
} LIMIT 20

